head.script:
// ===== 리턴 값 출력 영역 =====
scwin.btn_clear_onclick = function (e) {
    $p.getComponentById("tbx_return").setValue("");
};

scwin.setReturnValue = function (strValue) {
    var objReturn = $p.getComponentById("tbx_return");
    objReturn.setValue(objReturn.getValue() + strValue);
    objReturn.setValue(objReturn.getValue() + "\n");
};

// ===== 결함 재현 (5.0 vs 6.0 동작 비교) =====

// LinkedDataList 는 부모의 현재 Row 를 기준으로 묶이므로 초기 rowPosition 을 지정해
//  목록이 보이는 상태로 만든다. 모든 Row 가 cat1=A 라 rowPosition 이 바뀜도 목록 구성은 같고 순서만 문제가 된다.
scwin.onpageload = function () {
    $p.getComponentById("dlt_org").setRowPosition(0);
};

// LinkedDataList 의 현재 Row 순서를 한 줄로 만든다.
scwin.order = function () {
    var arrRow = $p.getComponentById("target1").getAllFilteredJSON();
    var arrText = [];
    for (var i = 0; i < arrRow.length; i++) {
        arrText.push(arrRow[i].col1);
    }
    return arrText.join(" > ");
};

// 정렬이 걸린 상태인지(= col1 내림차순인지) 판정한다.
//  내림차순 정렬 결과의 첫 항목은 websquare, 정렬이 풀린 원본 순서의 첫 항목은 WebSquare 다.
scwin.isSorted = function () {
    return (scwin.order().indexOf("websquare >") === 0);
};

scwin.btn_sort_onclick = function (e) {
    $p.getComponentById("target1").sort("col1", 1);

    scwin.setReturnValue("=====sort(\"col1\", 1) 적용=====");
    scwin.setReturnValue("    현재 순서 : " + scwin.order());
    scwin.setReturnValue("    정렬 적용됨 : " + (scwin.isSorted() ? "O" : "X"));
    scwin.setReturnValue("");
};

scwin.btn_move_onclick = function (e) {
    var objOrg = $p.getComponentById("dlt_org");
    var nBefore = objOrg.getRowPosition();
    var nNext = (nBefore === 0) ? 1 : 0;

    objOrg.setRowPosition(nNext);

    scwin.setReturnValue("=====부모 DataList rowPosition " + nBefore + " -> " + nNext + "=====");
    scwin.setReturnValue("    현재 순서 : " + scwin.order());
    scwin.setReturnValue("    정렬 유지됨 : " + (scwin.isSorted() ? "O" : "X"));
    scwin.setReturnValue("");
    scwin.setReturnValue("----- 판정 -----");
    if (scwin.isSorted()) {
        scwin.setReturnValue("부모 rowPosition 이 바뀌어도 LinkedDataList 의 정렬이 유지된다");
    } else {
        scwin.setReturnValue("부모 rowPosition 이 바뀌자 LinkedDataList 의 정렬이 해제되어 원본 순서로 돌아갔다");
    }
    scwin.setReturnValue("");
};
